Con soli nove aggiornamenti informativi per persona, una stima completamente separata è particolarmente fragile. Il dataset è quindi utile per mostrare perché il problema non possa essere risolto semplicemente assegnando due parametri liberi a ogni partecipante.

41.6.1 Un benchmark senza condivisione
Le stime seguenti vengono ottenute separatamente per ciascuna persona. Non costituiscono il modello inferenziale finale: rendono visibile quanto possano apparire diverse le persone quando nessuna informazione viene condivisa.






NotaApprofondimento applicativo: stime no pooling






predict_goal_path &lt;- function(goal, performance, alpha, beta) {
  mu &lt;- numeric(length(goal))
  mu[1] &lt;- goal[1]

  if (length(goal) &gt; 1) {
    for (t in 2:length(goal)) {
      mu[t] &lt;- mu[t - 1] +
        alpha * (performance[t - 1] - mu[t - 1]) +
        beta
    }
  }

  mu
}

estimate_no_pool_subject &lt;- function(goal, performance) {
  objective &lt;- function(theta) {
    alpha &lt;- plogis(theta[1])
    beta &lt;- theta[2]
    mu &lt;- predict_goal_path(goal, performance, alpha, beta)
    sum((goal[-1] - mu[-1])^2)
  }

  estimate &lt;- optim(
    par = c(qlogis(0.50), 0),
    fn = objective,
    method = "BFGS"
  )

  tibble(
    alpha_no_pool = plogis(estimate$par[1]),
    beta_no_pool = estimate$par[2],
    residual_ss = estimate$value
  )
}

no_pool_estimates &lt;- goal_data |&gt;
  group_by(subject, condition) |&gt;
  group_modify(
    ~ estimate_no_pool_subject(
      goal = .x$goal,
      performance = .x$performance
    )
  ) |&gt;
  ungroup()








