41.7.2 Implementazione e stima
Il programma seguente realizza il modello. Per comprendere il capitolo non è necessario seguire ogni istruzione: è sufficiente riconoscere la corrispondenza tra distribuzioni di popolazione, parametri individuali, dinamica e modello osservazionale.






NotaApprofondimento computazionale: modello gerarchico in Stan






stan_code_goal_hierarchical &lt;- "
data {
  int&lt;lower=1&gt; Ntotal;
  int&lt;lower=1&gt; Nsubj;
  array[Ntotal] int&lt;lower=1, upper=Nsubj&gt; subject;
  array[Ntotal] int&lt;lower=1&gt; trial;
  vector[Ntotal] goal;
  vector[Ntotal] performance;
}

parameters {
  real mu_alpha_logit;
  real&lt;lower=0&gt; tau_alpha_logit;
  vector[Nsubj] z_alpha;

  real mu_beta;
  real&lt;lower=0&gt; tau_beta;
  vector[Nsubj] z_beta;

  real&lt;lower=0&gt; sigma;
}

transformed parameters {
  vector[Nsubj] alpha_logit =
    mu_alpha_logit + tau_alpha_logit * z_alpha;
  vector&lt;lower=0, upper=1&gt;[Nsubj] alpha = inv_logit(alpha_logit);
  vector[Nsubj] beta = mu_beta + tau_beta * z_beta;
  vector[Ntotal] mu;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      mu[i] = goal[i];
    } else {
      int s = subject[i];
      mu[i] = mu[i - 1]
              + alpha[s] * (performance[i - 1] - mu[i - 1])
              + beta[s];
    }
  }
}

model {
  mu_alpha_logit ~ normal(0, 1);
  tau_alpha_logit ~ normal(0, 0.75);
  z_alpha ~ std_normal();

  mu_beta ~ normal(0, 0.25);
  tau_beta ~ normal(0, 0.25);
  z_beta ~ std_normal();

  sigma ~ normal(0, 0.75);

  for (i in 1:Ntotal) {
    if (trial[i] &gt; 1) {
      goal[i] ~ normal(mu[i], sigma);
    }
  }
}

generated quantities {
  real&lt;lower=0, upper=1&gt; alpha_typical = inv_logit(mu_alpha_logit);
  vector[Ntotal] y_rep;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      y_rep[i] = goal[i];
    } else {
      y_rep[i] = normal_rng(mu[i], sigma);
    }
  }
}
"


make_goal_stan_data &lt;- function(data) {
  data &lt;- data |&gt;
    arrange(subject, trial)

  list(
    Ntotal = nrow(data),
    Nsubj = n_distinct(data$subject),
    subject = data$subject,
    trial = data$trial,
    goal = data$goal,
    performance = data$performance
  )
}

stan_data_goal_hierarchical &lt;- make_goal_stan_data(goal_data)


model_goal_hierarchical &lt;- cmdstanr::cmdstan_model(
  cmdstanr::write_stan_file(stan_code_goal_hierarchical)
)

fit_goal_hierarchical &lt;- model_goal_hierarchical$sample(
  data = stan_data_goal_hierarchical,
  seed = 8061,
  chains = 4,
  parallel_chains = min(4, parallel::detectCores(logical = FALSE)),
  iter_warmup = 1500,
  iter_sampling = 2000,
  adapt_delta = 0.95,
  refresh = 500
)


fit_goal_hierarchical$summary(
  variables = c(
    "alpha_typical",
    "mu_beta",
    "tau_alpha_logit",
    "tau_beta",
    "sigma"
  )
) |&gt;
  select(variable, mean, median, sd, q5, q95, rhat, ess_bulk, ess_tail)









La convergenza del campionatore risponde alla domanda se la posterior sia stata esplorata adeguatamente. Non stabilisce se la distribuzione gerarchica sia una buona descrizione della popolazione o se i parametri possiedano il significato psicologico attribuito loro.

41.8 Dalla popolazione alle persone
La posterior permette di distinguere tre oggetti:

la posizione della popolazione;
la dispersione tra persone;
l’incertezza sui parametri di ciascuna persona.







NotaApprofondimento applicativo: posterior individuali e shrinkage






individual_alpha &lt;- fit_goal_hierarchical |&gt;
  spread_draws(alpha[subject]) |&gt;
  median_qi(alpha, .width = 0.90) |&gt;
  rename(
    alpha_lower = .lower,
    alpha_upper = .upper
  )

individual_beta &lt;- fit_goal_hierarchical |&gt;
  spread_draws(beta[subject]) |&gt;
  median_qi(beta, .width = 0.90) |&gt;
  rename(
    beta_lower = .lower,
    beta_upper = .upper
  )

individual_goal_parameters &lt;- individual_alpha |&gt;
  select(subject, alpha, alpha_lower, alpha_upper) |&gt;
  left_join(
    individual_beta |&gt;
      select(subject, beta, beta_lower, beta_upper),
    by = "subject"
  ) |&gt;
  left_join(subject_structure, by = "subject")








Figura 41.3: Posterior individuali di alpha. La larghezza degli intervalli descrive l’incertezza sulla persona; non deve essere confusa con la dispersione della popolazione.





shrinkage_goal &lt;- no_pool_estimates |&gt;
  left_join(
    individual_goal_parameters |&gt;
      select(subject, alpha_hier = alpha, beta_hier = beta),
    by = "subject"
